import java.util.*; public class Q11_UniversityHostelAllocation{static class Room{String no,b,t;Room(String n,String b,String t){no=n;this.b=b;this.t=t;}public String toString(){return "Room: "+no+" "+b+" "+t;}}static class Student{String n,r,c;Room room;Student(String n,String r,String c){this.n=n;this.r=r;this.c=c;}public String toString(){return "Student: "+n+" ("+r+") "+c+"\n"+room;}}public static void main(String[]x){Scanner s=new Scanner(System.in);String[]a=s.nextLine().split(","),p=s.nextLine().split(",");Student st=new Student(a[0],a[1],a[2]);st.room=new Room(p[0],p[1],p[2]);System.out.println(st);}}
